using Algorithms.Sorting;
namespace Algorithms.Graphs;
public static partial class GraphAlgorithms
{
    public static int[][] TarjanScc(int[][] graph) { var index = Enumerable.Repeat(-1, graph.Length).ToArray(); var low = new int[graph.Length]; var onStack = new bool[graph.Length]; var stack = new Stack<int>(); var result = new List<int[]>(); var counter = 0; void Connect(int v) { index[v] = low[v] = counter++; stack.Push(v); onStack[v] = true; foreach (var n in graph[v]) { if (index[n] == -1) { Connect(n); low[v] = Math.Min(low[v], low[n]); } else if (onStack[n]) low[v] = Math.Min(low[v], index[n]); } if (low[v] != index[v]) return; var component = new List<int>(); int node; do { node = stack.Pop(); onStack[node] = false; component.Add(node); } while (node != v); result.Add(Sort.MergeSort(component)); } for (var v = 0; v < graph.Length; v++) if (index[v] == -1) Connect(v); return result.ToArray(); }
    public static int[][] KosarajuScc(int[][] graph) { var reversed = graph.Select(_ => new List<int>()).ToArray(); for (var v = 0; v < graph.Length; v++) foreach (var n in graph[v]) reversed[n].Add(v); var visited = new bool[graph.Length]; var finish = new List<int>(); void Fill(int v) { visited[v] = true; foreach (var n in graph[v]) if (!visited[n]) Fill(n); finish.Add(v); } void Collect(int v, List<int> component) { visited[v] = true; component.Add(v); foreach (var n in reversed[v]) if (!visited[n]) Collect(n, component); } for (var v = 0; v < graph.Length; v++) if (!visited[v]) Fill(v); Array.Fill(visited, false); finish.Reverse(); var result = new List<int[]>(); foreach (var v in finish) { if (visited[v]) continue; var component = new List<int>(); Collect(v, component); result.Add(Sort.MergeSort(component)); } return result.ToArray(); }
}
